<template>
  <section class="oj-set-admin">
    <div class="set-heading"><h3>题单管理</h3><OjActionButton type="primary" @click="openEditor()" icon="plus">新建题单</OjActionButton></div>
    <form class="set-toolbar" @submit.prevent="page=1;load()"><el-input v-model="keyword" placeholder="搜索题单" clearable /><el-select v-model="mode" placeholder="全部模式" clearable @change="page=1;load()"><el-option label="练习模式" value="PRACTICE" /><el-option label="比赛模式" value="CONTEST" /></el-select><OjActionButton native-type="submit" :loading="loading" icon="search">搜索</OjActionButton><OjActionButton @click="load" icon="refresh">刷新</OjActionButton></form>
    <p v-if="error" class="set-error" role="alert">{{ error }}</p>
    <el-table :data="rows" v-loading="loading" row-key="id"><el-table-column label="题单" min-width="220"><template #default="{row}"><OjActionButton link icon="file" class="set-title" @click="openDetail(row.id)">{{ row.name }}</OjActionButton><small class="set-muted">{{ row.accessType==='WHITELIST'?'指定名单':'全站用户' }} · {{ row.languages.map(l=>languageNames[l]).join(' / ') }}</small></template></el-table-column><el-table-column label="模式" width="100"><template #default="{row}"><el-tag :type="row.mode==='CONTEST'?'warning':'success'">{{ row.mode==='CONTEST'?'比赛':'练习' }}</el-tag></template></el-table-column><el-table-column prop="total" label="题数" width="65" /><el-table-column prop="participants" label="参与人数" width="85" /><el-table-column label="状态" width="100"><template #default="{row}"><span :class="['set-phase',row.phase.toLowerCase()]"><i />{{ phases[row.phase] }}</span></template></el-table-column><el-table-column label="时间（北京时间）" min-width="175"><template #default="{row}"><template v-if="row.mode==='CONTEST'"><small>{{ date(row.startsAt) }}</small><small class="set-muted">至 {{ date(row.endsAt) }}</small></template><span v-else class="set-muted">不限时</span></template></el-table-column><el-table-column label="操作" min-width="265"><template #default="{row}"><div class="set-row-actions"><OjActionButton link type="primary" @click="openDetail(row.id)" icon="stats">记录与排名</OjActionButton><OjActionButton link type="primary" @click="openEditor(row.id)" icon="edit">编辑</OjActionButton><el-dropdown trigger="click"><OjActionButton link icon="more">更多</OjActionButton><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="row.status==='DRAFT'" @click="setStatus(row,'PUBLISHED')"><OjIcon name="download" :size="16" />发布题单</el-dropdown-item><el-dropdown-item v-if="row.status!=='ARCHIVED'" @click="setStatus(row,'ARCHIVED')"><OjIcon name="library" :size="16" />归档题单</el-dropdown-item><el-dropdown-item @click="copy(row)"><OjIcon name="copy" :size="16" />复制为草稿</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table>
    <el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load" />

    <el-dialog align-center v-model="editorOpen" :title="editingId?'编辑题单':'新建题单'" width="min(1060px,96vw)" class="set-editor" destroy-on-close>
      <div v-if="editorLoading" v-loading="true" class="set-loading" /><template v-else>
      <el-form label-position="top"><div class="set-form-grid"><el-form-item label="名称"><el-input v-model="form.name" maxlength="120" /></el-form-item><el-form-item label="模式"><el-radio-group v-model="form.mode" :disabled="locked || Number(form.participants)>0"><el-radio-button value="PRACTICE">练习模式</el-radio-button><el-radio-button value="CONTEST">比赛模式</el-radio-button></el-radio-group></el-form-item></div><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="2" maxlength="3000" /></el-form-item><div class="set-form-grid"><el-form-item label="参与范围"><el-select v-model="form.accessType" :disabled="locked"><el-option value="PUBLIC" label="全站登录用户" /><el-option value="WHITELIST" label="指定学号名单" /></el-select></el-form-item><el-form-item label="允许语言"><el-checkbox-group v-model="form.languages" :disabled="locked"><el-checkbox v-for="(name,key) in supportedLanguages" :key="key" :value="key">{{ name }}</el-checkbox></el-checkbox-group></el-form-item></div><el-form-item v-if="form.accessType==='WHITELIST'" label="学号名单（空格、逗号或换行分隔）"><el-input v-model="studentText" type="textarea" :rows="3" :disabled="locked" /></el-form-item><div v-if="form.mode==='CONTEST'" class="set-form-grid"><el-form-item label="开始时间（北京时间，可留空保存草稿）"><el-date-picker v-model="startText" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" :disabled="locked" placeholder="选择开始时间" /></el-form-item><el-form-item label="结束时间（北京时间）"><el-date-picker v-model="endText" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" :disabled="locked" placeholder="选择结束时间" /></el-form-item></div></el-form>
      <el-alert v-if="locked" title="比赛已开赛，当前只能编辑名称和说明。调整结束时间请使用“延长比赛”。" type="info" :closable="false" />
      <div class="set-selection-heading"><h4>已选题目 <span>{{ selected.length }}</span></h4><OjActionButton :disabled="locked" @click="pickerOpen=!pickerOpen;loadCatalog()" icon="plus">{{ pickerOpen?'收起选题':'添加题目' }}</OjActionButton></div>
      <div v-if="pickerOpen&&!locked" class="set-picker"><div class="set-picker-filters"><el-input v-model="pickerKeyword" placeholder="搜索题目" clearable /><el-select v-model="pickerDifficulty" placeholder="全部难度" clearable><el-option v-for="(name,key) in levels" :key="key" :label="name" :value="key" /></el-select><el-select v-model="pickerSource" placeholder="全部来源" clearable><el-option v-for="value in catalogSources" :key="value" :label="value" :value="value" /></el-select><el-select v-model="pickerTag" placeholder="全部算法类型" clearable><el-option v-for="value in catalogTags" :key="value" :label="value" :value="value" /></el-select></div><el-table :data="catalogFiltered" v-loading="catalogLoading" max-height="300"><el-table-column label="题目" min-width="220"><template #default="{row}">{{ row.title }}<small class="set-muted">{{ row.sourcePlatform }} · {{ row.status==='CONTEST_ONLY'?'仅管理端可见':'已发布' }}</small></template></el-table-column><el-table-column label="难度" width="80"><template #default="{row}">{{ levels[row.difficulty] }}</template></el-table-column><el-table-column label="模式" min-width="130"><template #default="{row}">{{ row.modes.map(m=>modeNames[m]).join(' / ') }}</template></el-table-column><el-table-column width="75"><template #default="{row}"><OjActionButton link type="primary" :disabled="selected.some(i=>String(i.problemId)===String(row.id))" @click="addProblem(row)" icon="plus">添加</OjActionButton></template></el-table-column></el-table></div>
      <p v-if="!selected.length" class="set-muted">尚未选择题目</p><div v-for="(i,index) in selected" :key="i.problemId" class="set-selected-row" :draggable="!locked" @dragstart="dragIndex=index" @dragover.prevent @drop="drop(index)"><span class="set-number">{{ index+1 }}</span><div class="set-selected-title"><strong>{{ i.title }}</strong><small>{{ levels[i.difficulty] }} · {{ i.sourcePlatform }}</small></div><el-checkbox-group v-model="i.modes" :disabled="locked"><el-checkbox v-for="m in i.availableModes" :key="m" :value="m">{{ modeNames[m] }}</el-checkbox></el-checkbox-group><div class="set-move"><OjActionButton circle :disabled="locked||index===0" :aria-label="`上移 ${i.title}`" @click="move(index,-1)"  icon="arrow-up" /><OjActionButton circle :disabled="locked||index===selected.length-1" :aria-label="`下移 ${i.title}`" @click="move(index,1)"  icon="arrow-down" /><OjActionButton circle :disabled="locked" :aria-label="`移除 ${i.title}`" @click="selected.splice(index,1)"  icon="trash" /></div></div>
      </template><template #footer><OjActionButton @click="editorOpen=false" icon="close">取消</OjActionButton><OjActionButton type="primary" :loading="saving" :disabled="editorLoading" @click="save" icon="save">保存{{ editingId?'':'草稿' }}</OjActionButton></template>
    </el-dialog>

    <el-dialog align-center v-model="detailOpen" title="题单详情" width="min(1200px,96vw)" destroy-on-close>
      <div v-if="detailLoading" v-loading="true" class="set-loading" /><template v-else-if="detail"><div class="set-detail-heading"><div><h3>{{ detail.name }}</h3><p>{{ detail.mode==='CONTEST'?'比赛':'练习' }} · {{ detail.total }} 道题 · {{ detail.participants }} 人参与 · {{ phases[detail.phase] }}</p></div><OjActionButton :loading="refreshing" @click="refreshDetail" icon="refresh">刷新</OjActionButton></div><div v-if="detail.mode==='CONTEST'" class="set-contest-controls"><span>{{ date(detail.startsAt) }} — {{ date(detail.endsAt) }}</span><OjActionButton v-if="detail.canExtend" size="small" @click="extendOpen=true;extendedText=toInput(detail.endsAt)" icon="clock">延长比赛</OjActionButton><el-switch v-if="detail.phase==='ENDED' || detail.phase==='ARCHIVED'&&detail.endsAt&&Date.now()>=Number(detail.endsAt)" :model-value="detail.publicCode" active-text="赛后公开代码" @change="setPublicCode" /></div>
      <el-tabs v-model="detailTab" @tab-change="loadDetailTab"><el-tab-pane name="problems" label="题目"><template #label><OjIcon name="library" :size="16" /> 题目</template><el-table :data="detail.items"><el-table-column prop="label" label="题号" width="65" /><el-table-column label="题目" min-width="240"><template #default="{row}"><OjActionButton link icon="edit" class="set-title" @click="editProblem(row.problemId)">{{ row.title }}</OjActionButton><small class="set-muted">{{ row.modes.map(m=>modeNames[m]).join(' / ') }} · 版本 {{ row.revision }}</small></template></el-table-column><el-table-column label="难度" width="85"><template #default="{row}">{{ levels[row.difficulty] }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{ row.active?'有效':'已作废' }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><OjActionButton v-if="row.active" link type="danger" @click="cancelItem(row)" icon="ban">作废</OjActionButton></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane name="history" label="提交记录"><template #label><OjIcon name="history" :size="16" /> 提交记录</template><div class="set-history-toolbar"><el-select v-model="historyItem" clearable placeholder="全部题目" @change="historyPage=1;loadHistory()"><el-option v-for="i in detail.items" :key="i.id" :value="String(i.id)" :label="`${i.label}. ${i.title}`" /></el-select><el-select v-model="historyStatus" clearable placeholder="全部结果" @change="historyPage=1;loadHistory()"><el-option v-for="value in verdicts" :key="value" :value="value" :label="ojStatuses[value].label" /></el-select></div><el-table :data="history" v-loading="historyLoading"><el-table-column prop="id" label="提交" width="85" /><el-table-column prop="problemTitle" label="题目" min-width="170" /><el-table-column label="用户" min-width="170"><template #default="{row}">{{ row.name }}（{{ row.nickname }}）<small class="set-muted">{{ row.studentId }}</small></template></el-table-column><el-table-column label="语言 / 模式" width="150"><template #default="{row}">{{ languageNames[row.language] }}<small class="set-muted">{{ modeNames[row.mode] }} · {{ kindNames[row.kind] }}</small></template></el-table-column><el-table-column label="结果" width="110"><template #default="{row}"><OjStatusBadge :status="row.status" /></template></el-table-column><el-table-column label="接收时间" min-width="170"><template #default="{row}">{{ date(row.acceptedAt) }}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><OjActionButton link type="primary" @click="showCode(row)" icon="code">代码</OjActionButton><OjActionButton link type="primary" :disabled="row.kind!=='SUBMIT'||['QUEUED','RUNNING'].includes(row.status)" @click="rejudge(row)" icon="refresh">重判</OjActionButton></template></el-table-column></el-table><el-pagination v-model:current-page="historyPage" :total="historyTotal" :page-size="50" layout="total,prev,pager,next" @current-change="loadHistory" /></el-tab-pane>
      <el-tab-pane name="ranking" label="完成名单与排名"><template #label><OjIcon name="stats" :size="16" /> 完成名单与排名</template><div class="set-heading"><el-checkbox v-model="completedOnly" @change="rankPage=1;loadRanking()">仅显示完成全部题目</el-checkbox><OjActionButton :disabled="!ranking.length" @click="exportRanking" icon="download">导出成绩</OjActionButton></div><el-table :data="ranking" v-loading="rankLoading"><el-table-column prop="rank" label="排名" width="65" /><el-table-column label="用户" min-width="180"><template #default="{row}">{{ row.name }}（{{ row.nickname }}）<small class="set-muted">{{ row.studentId }}</small></template></el-table-column><el-table-column label="通过" width="90"><template #default="{row}">{{ row.acCount }} / {{ rankTotals.total }}</template></el-table-column><el-table-column v-if="detail.mode==='CONTEST'" prop="penalty" label="罚时（分）" width="100" /><el-table-column v-for="i in detail.items.filter(i=>i.active)" :key="i.id" :label="i.label" width="80"><template #default="{row}"><span :class="['set-score',{ac:row.cells[i.id]?.accepted}]"><strong>{{ row.cells[i.id]?.accepted?'AC':Number(row.cells[i.id]?.pending)>0?'判题中':Number(row.cells[i.id]?.wrong)>0?'−'+row.cells[i.id].wrong:'—' }}</strong><small v-if="detail.mode==='CONTEST'&&row.cells[i.id]?.accepted">{{ row.cells[i.id].elapsedMinutes }} (+{{ row.cells[i.id].wrong }})</small></span></template></el-table-column><el-table-column label="完成时间" min-width="175"><template #default="{row}">{{ row.completedAt?date(row.completedAt):'未完成' }}</template></el-table-column><el-table-column label="资格" width="110"><template #default="{row}"><OjActionButton link :type="row.disqualified?'success':'danger'" @click="qualification(row)" :icon="row.disqualified?'shield':'ban'">{{ row.disqualified?'恢复资格':'取消资格' }}</OjActionButton></template></el-table-column></el-table><el-pagination v-model:current-page="rankPage" :total="rankTotal" :page-size="50" layout="total,prev,pager,next" @current-change="loadRanking" /></el-tab-pane>
      <el-tab-pane name="audit" label="操作记录"><template #label><OjIcon name="timeline" :size="16" /> 操作记录</template><el-table :data="detail.audit"><el-table-column label="时间" min-width="170"><template #default="{row}">{{ date(row.createdAt) }}</template></el-table-column><el-table-column label="操作" min-width="160"><template #default="{row}">{{ auditNames[row.action] || row.action }}</template></el-table-column><el-table-column prop="actorId" label="操作账号ID" width="110" /><el-table-column prop="jobId" label="提交ID" width="90" /><el-table-column prop="reason" label="原因" min-width="220" /></el-table></el-tab-pane></el-tabs></template>
    </el-dialog>
    <el-dialog align-center v-model="codeOpen" title="提交代码" width="min(1000px,95vw)" destroy-on-close><p v-if="codeLoading">正在加载代码…</p><template v-if="source"><p>{{ languageNames[source.language] }} · {{ modeNames[source.mode] }} <OjStatusBadge :status="source.status" /></p><OjCodeEditor :model-value="source.code" :language="source.language" read-only label="题单提交代码" /></template></el-dialog>
    <el-dialog align-center v-model="extendOpen" title="延长比赛" width="min(480px,94vw)"><el-form label-position="top"><el-form-item label="新的结束时间（北京时间）"><el-date-picker v-model="extendedText" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" /></el-form-item><el-form-item label="原因"><el-input v-model="extendReason" type="textarea" :rows="3" maxlength="500" /></el-form-item></el-form><template #footer><OjActionButton @click="extendOpen=false" icon="close">取消</OjActionButton><OjActionButton type="primary" @click="extendContest" icon="save">保存</OjActionButton></template></el-dialog>
  </section>
</template>
<script setup>
import OjActionButton from '@/components/OjActionButton.vue'
import OjIcon from '@/components/OjIcon.vue'
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import OjStatusBadge from './OjStatusBadge.vue'
import OjCodeEditor from './OjCodeEditor.vue'
import {ojStatuses,languageNames,modeNames,kindNames} from '@/utils/ojDictionaries'
const emit=defineEmits(['editProblem'])
const base='/api/admin/oj/sets',levels={EASY:'简单',MEDIUM:'中等',HARD:'困难'},supportedLanguages={c:'C',cpp:'C++',java:'Java',python:'Python',rust:'Rust'}
const phases={DRAFT:'草稿',PRACTICE:'练习中',UPCOMING:'未开始',RUNNING:'进行中',ENDED:'已结束',ARCHIVED:'已归档'}
const auditNames={CREATE:'创建',EDIT:'编辑',EDIT_METADATA:'编辑展示信息',PUBLISHED:'发布',ARCHIVED:'归档',OPEN_CODE:'公开赛后代码',CLOSE_CODE:'关闭代码公开',CANCEL_ITEM:'作废题目',EXTEND:'延长比赛',DISQUALIFY:'取消资格',RESTORE:'恢复资格',REJUDGE:'重判'}
const date=t=>t?new Date(Number(t)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未设置'
function toInput(t){if(!t)return '';const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(Number(t)));return parts}
const epoch=text=>text?new Date(text.replace(' ','T')+'+08:00').getTime():null
const rows=ref([]),loading=ref(false),error=ref(''),page=ref(1),total=ref(0),keyword=ref(''),mode=ref('');let disposed=false,listGeneration=0
async function load(){const generation=++listGeneration;loading.value=true;error.value='';try{const{data}=await request.get(base,{params:{keyword:keyword.value,mode:mode.value,page:page.value}});if(!disposed&&generation===listGeneration){rows.value=data.records;total.value=Number(data.total)}}catch(e){error.value=e.message}finally{if(generation===listGeneration)loading.value=false}}
const editorOpen=ref(false),editorLoading=ref(false),editingId=ref(null),saving=ref(false),form=ref({}),selected=ref([]),studentText=ref(''),startText=ref(''),endText=ref(''),locked=ref(false),pickerOpen=ref(false)
async function openEditor(id){editingId.value=id||null;editorOpen.value=true;editorLoading.value=true;pickerOpen.value=false;error.value='';try{let data=id?(await request.get(`${base}/${id}`)).data:{name:'',description:'',mode:'PRACTICE',accessType:'PUBLIC',languages:Object.keys(supportedLanguages),students:[],items:[],status:'DRAFT'};form.value=data;studentText.value=data.students.join('\n');startText.value=toInput(data.startsAt);endText.value=toInput(data.endsAt);locked.value=data.mode==='CONTEST'&&data.status!=='DRAFT'&&data.startsAt&&Date.now()>=Number(data.startsAt);selected.value=data.items.filter(i=>i.active).map(i=>({...i,availableModes:[...i.modes]}));await loadCatalog();selected.value.forEach(i=>{const p=catalog.value.find(p=>String(p.id)===String(i.problemId));if(p)i.availableModes=[...new Set([...p.modes,...i.modes])]})}catch(e){ElMessage.error(e.message);editorOpen.value=false}finally{editorLoading.value=false}}
const catalog=ref([]),catalogLoading=ref(false),pickerKeyword=ref(''),pickerDifficulty=ref(''),pickerSource=ref(''),pickerTag=ref('')
const catalogSources=computed(()=>[...new Set(catalog.value.map(p=>p.sourcePlatform))]),catalogTags=computed(()=>[...new Set(catalog.value.flatMap(p=>p.tags))].sort())
const catalogFiltered=computed(()=>catalog.value.filter(p=>p.validated&&['PUBLISHED','CONTEST_ONLY'].includes(p.status)&&(form.value.mode==='CONTEST'||p.status==='PUBLISHED')&&(!pickerKeyword.value||p.title.toLowerCase().includes(pickerKeyword.value.toLowerCase()))&&(!pickerDifficulty.value||p.difficulty===pickerDifficulty.value)&&(!pickerSource.value||p.sourcePlatform===pickerSource.value)&&(!pickerTag.value||p.tags.includes(pickerTag.value))))
async function loadCatalog(){if(catalogLoading.value)return;catalogLoading.value=true;try{const all=[];let page=1,total=1;while(all.length<total){const{data}=await request.get('/api/admin/oj/problems',{params:{page,size:50}});all.push(...data.records);total=Number(data.total);page++;if(!data.records.length)break}catalog.value=all}catch(e){ElMessage.error(e.message)}finally{catalogLoading.value=false}}
function addProblem(p){selected.value.push({problemId:p.id,title:p.title,difficulty:p.difficulty,sourcePlatform:p.sourcePlatform,modes:[...p.modes],availableModes:[...p.modes]})}
function move(index,delta){const row=selected.value.splice(index,1)[0];selected.value.splice(index+delta,0,row)}
let dragIndex=null
function drop(index){if(locked.value||dragIndex===null)return;const row=selected.value.splice(dragIndex,1)[0];selected.value.splice(index,0,row);dragIndex=null}
async function save(){if(!form.value.name.trim()||!selected.value.length){ElMessage.warning('请填写名称并选择题目');return}saving.value=true;try{const payload={name:form.value.name,description:form.value.description,mode:form.value.mode,accessType:form.value.accessType,languages:form.value.languages,students:[...new Set(studentText.value.split(/[\s,，]+/).filter(Boolean))],startsAt:epoch(startText.value),endsAt:epoch(endText.value),revision:form.value.revision,items:selected.value.map(i=>({problemId:i.problemId,modes:i.modes}))};await request[editingId.value?'put':'post'](editingId.value?`${base}/${editingId.value}`:base,payload);editorOpen.value=false;ElMessage.success('题单已保存');await load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
async function setStatus(s,status){try{if(status==='ARCHIVED')await ElMessageBox.confirm('归档后保留记录与排名，停止新提交。','归档题单',{type:'warning'});await request.put(`${base}/${s.id}/status`,{status});ElMessage.success(status==='PUBLISHED'?'已发布':'已归档');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}
async function copy(s){try{const{data}=await request.post(`${base}/${s.id}/copy`);await load();openEditor(data.id)}catch(e){ElMessage.error(e.message)}}
const detailOpen=ref(false),detailLoading=ref(false),detail=ref(null),detailTab=ref('problems'),refreshing=ref(false)
async function openDetail(id){detailOpen.value=true;detailLoading.value=true;detailTab.value='problems';historyPage.value=1;rankPage.value=1;historyItem.value='';historyStatus.value='';try{detail.value=(await request.get(`${base}/${id}`)).data}catch(e){ElMessage.error(e.message);detailOpen.value=false}finally{detailLoading.value=false}}
function editProblem(id){detailOpen.value=false;emit('editProblem',id)}
async function refreshDetail(){if(refreshing.value||!detail.value)return;refreshing.value=true;try{detail.value=(await request.get(`${base}/${detail.value.id}`)).data;await loadDetailTab()}catch(e){ElMessage.error(e.message)}finally{refreshing.value=false}}
async function loadDetailTab(){if(detailTab.value==='history')await loadHistory();if(detailTab.value==='ranking')await loadRanking()}
const history=ref([]),historyLoading=ref(false),historyItem=ref(''),historyStatus=ref(''),historyTotal=ref(0),historyPage=ref(1),verdicts=['AC','WA','CE','TLE','MLE','RE','OLE','SYSTEM_ERROR','QUEUED','RUNNING']
async function loadHistory(){if(!detail.value)return;historyLoading.value=true;try{const{data}=await request.get(`${base}/${detail.value.id}/submissions`,{params:{page:historyPage.value,itemId:historyItem.value||undefined,status:historyStatus.value}});history.value=data.records;historyTotal.value=Number(data.total)}catch(e){ElMessage.error(e.message)}finally{historyLoading.value=false}}
const ranking=ref([]),rankLoading=ref(false),rankTotal=ref(0),rankPage=ref(1),completedOnly=ref(false),rankTotals=ref({total:0})
async function loadRanking(){if(!detail.value)return;rankLoading.value=true;try{const{data}=await request.get(`${base}/${detail.value.id}/ranking`,{params:{page:rankPage.value,completed:completedOnly.value}});ranking.value=data.records;rankTotal.value=Number(data.total);rankTotals.value=data.totals}catch(e){ElMessage.error(e.message)}finally{rankLoading.value=false}}
const codeOpen=ref(false),codeLoading=ref(false),source=ref(null)
async function showCode(row){codeOpen.value=true;codeLoading.value=true;source.value=null;try{source.value=(await request.get(`${base}/${detail.value.id}/submissions/${row.id}/code`)).data}catch(e){ElMessage.error(e.message)}finally{codeLoading.value=false}}
async function withReason(title,callback){try{const{value}=await ElMessageBox.prompt('填写操作原因',title,{inputType:'textarea',inputValidator:v=>v&&v.trim().length>0&&v.length<=500||'请输入 1–500 字符的原因'});await callback(value);ElMessage.success('操作已保存');await refreshDetail();load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}
const cancelItem=i=>withReason('作废 '+i.title,reason=>request.post(`${base}/${detail.value.id}/items/${i.id}/cancel`,{reason}))
const rejudge=r=>withReason('重判提交 #'+r.id,reason=>request.post(`${base}/${detail.value.id}/submissions/${r.id}/rejudge`,{reason}))
const qualification=r=>withReason(r.disqualified?'恢复参与资格':'取消参与资格',reason=>request.put(`${base}/${detail.value.id}/participants`,{userId:r.userId,disqualified:!r.disqualified,reason}))
async function setPublicCode(value){try{await request.put(`${base}/${detail.value.id}/public-code`,{publicCode:value});detail.value.publicCode=value;await refreshDetail()}catch(e){ElMessage.error(e.message)}}
const extendOpen=ref(false),extendedText=ref(''),extendReason=ref('')
async function extendContest(){try{await request.post(`${base}/${detail.value.id}/extend`,{endsAt:epoch(extendedText.value),reason:extendReason.value});extendOpen.value=false;extendReason.value='';await refreshDetail();load()}catch(e){ElMessage.error(e.message)}}
async function exportRanking(){try{const all=[];let p=1,total=1;while(all.length<total){const{data}=await request.get(`${base}/${detail.value.id}/ranking`,{params:{page:p,completed:completedOnly.value}});all.push(...data.records);total=Number(data.total);p++;if(!data.records.length)break}const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv=[['排名','姓名','昵称','学号','通过题数','总题数','罚时(分钟)','完成时间'],...all.map(r=>[r.rank,r.name,r.nickname,r.studentId,r.acCount,rankTotals.value.total,r.penalty,r.completedAt?date(r.completedAt):''])].map(r=>r.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=detail.value.name+'-成绩.csv';a.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error(e.message)}}
let timer
onMounted(()=>{load();timer=setInterval(()=>{if(detailOpen.value&&!document.hidden)refreshDetail()},5000)})
onBeforeUnmount(()=>{disposed=true;listGeneration++;clearInterval(timer)})
</script>
